import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"值预测直觉","description":"","frontmatter":{"title":"值预测直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/value-prediction.md","filePath":"cs/value-prediction.md","lastUpdated":1789023840000}'),c={name:"cs/value-prediction.md"};function h(B,a,_,A,m,u){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="值预测直觉" tabindex="-1">值预测直觉 <a class="header-anchor" href="#值预测直觉" aria-label="Permalink to &quot;值预测直觉&quot;">​</a></h1><div class="epigraph"><p>数据流极限说：没有操作数就不能算。若操作数常常等于上次或等于一个可预测常数，可以先用猜测值算，核对失败再像误预测一样冲刷。</p><footer>—— 据 Lipasti and Shen, Exceeding the Dataflow Limit via Value Prediction, MICRO 1996 整理</footer></div><p><a href="/cs/store-set-predict">上一课</a>预测的是「要不要等」，不是「值是多少」。寄存器 RAW 在<a href="/cs/register-renaming">重命名</a>之后仍是硬边：源物理寄存器未写回则不能选发。本课不重训 SSID。缺口是<strong>值预测</strong>：猜源操作数或 load 返回值，把数据流边变成可撤销的推测边。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>许多指令的结果是上次同一 PC 的结果（可步长、可不变）：循环感应变量、函数返回的错误码、反复读同一内存。若等真值，窗口在长延迟 load 上枯竭。<a href="/cs/mshr">MLP</a> 能重叠缺失，但依赖链上的 ALU 仍串着。缺口不是更大的 IQ，而是<strong>把「上次值 / 步长」当成预测操作数，核对写回时比较</strong>。</p><p><span class="marginnote">Lipasti–Shen 指出：正确性仍靠核对；值预测提高的是有效 ILP，失败代价类似分支误预测。后续研究对整数 ALU 收益有限，对长延迟 load 更有吸引力。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按指令 PC 建值历史表：上一结果、可选步长、置信度。高置信则把猜测值写入「假就绪」的物理槽或旁路给消费者。真实结果写回时比较：相等则当什么都没发生；不等则冲刷该指令之后的窗口（或精确 replay 依赖链）。</p>',8)),(e(),n(p,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PC%5B%22%E6%8C%87%E4%BB%A4%20PC%22%5D%20--%3E%20VT%5B%22%E5%80%BC%E5%8E%86%E5%8F%B2%20%2F%20%E6%AD%A5%E9%95%BF%22%5D%0A%20%20VT%20--%3E%20SPEC%5B%22%E9%AB%98%E7%BD%AE%E4%BF%A1%E5%88%99%E5%BD%93%E6%93%8D%E4%BD%9C%E6%95%B0%E5%B0%B1%E7%BB%AA%22%5D%0A%20%20SPEC%20--%3E%20CONS%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%E6%8F%90%E5%89%8D%E6%89%A7%E8%A1%8C%22%5D%0A%20%20REAL%5B%22%E7%9C%9F%E5%AE%9E%E5%86%99%E5%9B%9E%22%5D%20--%3E%20CMP%5B%22%E4%B8%8E%E7%8C%9C%E6%B5%8B%E6%AF%94%E8%BE%83%22%5D%0A%20%20CMP%20--%3E%7C%22%E4%B8%8D%E7%AD%89%22%7C%20FLUSH%5B%22%E5%86%B2%E5%88%B7%E4%BE%9D%E8%B5%96%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>load 值预测可与<a href="/cs/store-set-predict">存储集</a> 叠：先猜不依赖，再猜数据；任一失败都要恢复。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这是<a href="/cs/speculation-recovery">推测恢复</a> 的第三种触发源：分支错、内存消歧错、值错。检查点必须能区分，否则一次值误预测会把 GHR 也卷回去——实现上值检查点可以更局部。置信度训练与循环器类似：规律才猜，随机数据不要猜。</p><p>商业核长期对通用值预测谨慎：核对带宽、错误冲刷、以及与内存模型交互的复杂度，往往吃掉收益。教学上它标明数据流极限不是物理极限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把神经网络值预测、也不把「预言执行」写成产品方案。不要与分支方向预测混淆：方向是控制流，值是数据流。前端取指宽度仍可能在值预测很准时成为瓶颈——那是下一课取指译码带宽。</p><p>后课默认：数据流边原则上可被值猜测暂时切断，但正确性永远在核对。窗口填满之后，首先卡住的常常是 IF/ID，不是 ALU。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>值预测用历史猜测操作数，核对失败则冲刷。</li><li>它超过经典数据流极限，但误预测很贵，实践中多限于特殊情况。</li><li>前端每拍能送进多少条，是下一课带宽。</li><li>出处：Lipasti and Shen, <em>MICRO</em>, 1996。</li></ul>',9))])}const P=o(c,[["render",h]]);export{f as __pageData,P as default};
